<template><div><div class="page-header"><div><h1 class="page-title">Chart 仓库</h1><p class="page-subtitle">管理平台扩展使用的 Helm Chart 来源与固定版本</p></div><button class="btn btn-primary" @click="openCreate">+ 新建 Chart 仓库</button></div><div v-if="error" class="k8s-banner k8s-banner-warn section-gap">{{ error }}</div><div v-if="loaded&&items.length" class="card section-gap"><div class="table-wrap"><table class="data-table"><thead><tr><th>名称</th><th>仓库地址</th><th>Chart</th><th>版本</th><th>状态</th><th>检测</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td class="cell-primary">{{item.name}}</td><td>{{item.endpoint}}</td><td>{{item.chart_name}}</td><td>{{item.chart_version}}</td><td><span class="badge" :class="item.enabled?'badge-online':'badge-offline'">{{item.enabled?'已启用':'已停用'}}</span></td><td><span class="badge" :class="item.last_verify_status==='succeeded'?'badge-online':item.last_verify_status==='failed'?'badge-danger':'badge-offline'">{{item.last_verify_status==='succeeded'?'可用':item.last_verify_status==='failed'?'失败':'未检测'}}</span><small v-if="item.last_verify_error" class="detail">{{item.last_verify_error}}</small></td><td><div class="btn-group"><button class="btn btn-sm" @click="verify(item)">检测</button><button class="btn btn-sm" @click="edit(item)">编辑</button><button class="btn btn-sm btn-danger" @click="target=item">删除</button></div></td></tr></tbody></table></div></div><div v-if="modal" class="overlay" @click.self="close"><div class="modal"><h2 class="modal-title">{{editing?'编辑 Chart 仓库':'新建 Chart 仓库'}}</h2><form @submit.prevent="save"><div class="form-group"><label class="form-label">名称</label><input v-model.trim="form.name" required class="form-input" placeholder="jetstack"/></div><div class="form-group"><label class="form-label">仓库地址</label><input v-model.trim="form.endpoint" required type="url" class="form-input" placeholder="https://charts.jetstack.io"/></div><div class="form-row"><div class="form-group"><label class="form-label">Chart 名称</label><input v-model.trim="form.chart_name" required class="form-input" placeholder="cert-manager"/></div><div class="form-group"><label class="form-label">固定版本</label><input v-model.trim="form.chart_version" required class="form-input" placeholder="v1.16.3"/></div></div><label class="check-row"><input v-model="form.enabled" type="checkbox"/> 启用此仓库</label><div class="modal-actions"><button type="button" class="btn" @click="close">取消</button><button class="btn btn-primary" :disabled="saving">保存</button></div></form></div></div><div v-if="target" class="overlay"><div class="modal"><h2 class="modal-title">删除 Chart 仓库</h2><div class="modal-actions"><button class="btn" @click="target=null">取消</button><button class="btn btn-danger" @click="remove">删除</button></div></div></div></div></template>
<script setup>import{onMounted,ref}from'vue';import{api}from'../api/index.js';const items=ref([]),loaded=ref(false),error=ref(''),modal=ref(false),editing=ref(null),target=ref(null),saving=ref(false),form=ref(blank());function blank(){return{name:'',endpoint:'',chart_name:'cert-manager',chart_version:'v1.16.3',enabled:true}}async function load(){try{items.value=await api.get('/chart-repositories')||[]}catch(e){error.value=e.message||'加载 Chart 仓库失败'}finally{loaded.value=true}}function openCreate(){editing.value=null;form.value=blank();modal.value=true}function edit(x){editing.value=x;form.value={name:x.name,endpoint:x.endpoint,chart_name:x.chart_name,chart_version:x.chart_version,enabled:x.enabled};modal.value=true}function close(){modal.value=false;editing.value=null}async function save(){saving.value=true;try{if(editing.value)await api.put(`/chart-repositories/${editing.value.id}`,form.value);else await api.post('/chart-repositories',form.value);close();await load()}catch(e){error.value=e.message||'保存失败'}finally{saving.value=false}}async function verify(x){try{await api.post(`/chart-repositories/${x.id}/verify`);await load()}catch(e){error.value=e.message||'检测失败'}}async function remove(){try{await api.delete(`/chart-repositories/${target.value.id}`);target.value=null;await load()}catch(e){error.value=e.message||'删除失败'}}onMounted(load)</script><style scoped>.page-header{display:flex;justify-content:space-between;gap:16px}.detail{display:block;max-width:220px;color:var(--danger);overflow-wrap:anywhere}.check-row{display:flex;gap:8px;margin:12px 0;color:var(--text-secondary);font-size:13px}@media(max-width:640px){.page-header{flex-direction:column}.page-header .btn{width:100%}}</style>
